import{o as s,c as i,a0 as n,j as o,t as d,p as r}from"./chunks/framework.L_oL6aia.js";const l={class:"rock-card-contact",style:{"margin-top":"2.5rem"}},c={class:"rock-copy-email-wrapper"},h=JSON.parse('{"title":"Tattoo You: Manual de Usuario","description":"","frontmatter":{},"headers":[],"relativePath":"es/tattoo-you.md","filePath":"es/tattoo-you.md"}'),u={name:"es/tattoo-you.md"},b=Object.assign(u,{setup(p){const a=r("Copiar Correo");function t(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),a.value="¡Copiado!",setTimeout(function(){a.value="Copiar Correo"},2e3)}return(g,e)=>(s(),i("div",null,[e[3]||(e[3]=n(`<h1 id="tattoo-you-manual-de-usuario" tabindex="-1">Tattoo You: Manual de Usuario <a class="header-anchor" href="#tattoo-you-manual-de-usuario" aria-label="Permalink to &quot;Tattoo You: Manual de Usuario&quot;">​</a></h1><p><strong>Versión 1.0.0 · Simulación de Amplificador Virtual &amp; Suite de FX Vintage</strong></p><img src="/tattoo-you.png" alt="Tattoo You Plugin GUI" style="max-height:300px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><blockquote><p><strong>Creado por Fans de los Stones, para Guitarristas:</strong><br><strong>Tattoo You</strong> nació de estudiar minuciosamente cada detalle, cinta de sesión y pista en vivo del sonido de guitarra de los Rolling Stones. Creado por fanáticos incondicionales de los Stones y guitarristas experimentados, está diseñado para que simplemente conectes tu guitarra, subas el volumen y te sumerjas de inmediato en el legendario tono de la era 1978–1981, con toda la sensibilidad al tacto, potencia y arrogancia de las grabaciones originales.</p></blockquote><hr><h2 id="_1-filosofia-de-diseno-la-era-dorada-de-bulbos-fx-1978–1981" tabindex="-1">1. Filosofía de Diseño: La Era Dorada de Bulbos &amp; FX (1978–1981) <a class="header-anchor" href="#_1-filosofia-de-diseno-la-era-dorada-de-bulbos-fx-1978–1981" aria-label="Permalink to &quot;1. Filosofía de Diseño: La Era Dorada de Bulbos &amp; FX (1978–1981)&quot;">​</a></h2><p><strong>Tattoo You</strong> captura el sonido definitivo de guitarra de estudio y escenario de finales de los 70 y principios de los 80 de Keith Richards y los Rolling Stones. Esta era marcó una transición sonora histórica: el paso de la saturación suelta y cruda de los viejos Tweed al diseño de alta ganancia en cascada y gran margen dinámico (headroom) de los <strong>cabezales de bulbos Mesa/Boogie 100W 6L6</strong> combinados con <strong>altavoces 1x12 Electro-Voice EVM-12L</strong> y modulación analógica frontal.</p><h3 id="la-linea-de-tiempo-historica-1978–1981" tabindex="-1">La Línea de Tiempo Histórica: 1978–1981 <a class="header-anchor" href="#la-linea-de-tiempo-historica-1978–1981" aria-label="Permalink to &quot;La Línea de Tiempo Histórica: 1978–1981&quot;">​</a></h3><ol><li><p><strong>Las Sesiones de París (1978 · <em>Some Girls</em> / <em>Beast of Burden</em>):</strong><br> En los <em>Pathé Marconi Studios</em> de París, Keith introdujo la icónica combinación de tonos limpios de bulbos comprimidos, el barrido óptico líquido del <strong>Phase &#39;78</strong> (estilo MXR Phase 100) y el cálido eco de cinta analógica slapback, inmortalizados en las texturas de guitarra características de <em>&quot;Beast of Burden&quot;</em>, <em>&quot;Miss You&quot;</em> y <em>&quot;Shattered&quot;</em>.</p></li><li><p><strong>La Era del Overdrive Tropical (1979–1980 · <em>Emotional Rescue</em>):</strong><br> Continuando entre París y <em>Compass Point Studios</em> (Nassau), el equipo evolucionó para manejar dinámicas ajustadas de funk-rock (<em>&quot;Emotional Rescue&quot;</em>, <em>&quot;Dance Part 1&quot;</em>), skanks mordaces de reggae-rock y solos de blues crujientes con una sensibilidad de púa y un headroom sin precedentes.</p></li><li><p><strong>El Poder de los Riffs Maestros (1981 · <em>Tattoo You</em>):</strong><br> Ensamblado entre París y <em>Atlantic Studios</em> (Nueva York), <em>Tattoo You</em> representa el cénit de este equipamiento. El inolvidable crujido rítmico en <em>&quot;Start Me Up&quot;</em>, la potencia impulsora de <em>&quot;Little T&amp;A&quot;</em>, el groove grasiento de <em>&quot;Slave&quot;</em> y la agresión rugiente de <em>&quot;Hang Fire&quot;</em> y <em>&quot;Neighbours&quot;</em> se erigen como referencias fundamentales para el tono de la guitarra rock.</p></li></ol><p>👉 <a href="/es/history-mesa-stones.html"><strong>Lee la historia completa: Cómo los Stones adquirieron los equipos Mesa/Boogie (1978–1981) →</strong></a></p><hr><h2 id="_2-arquitectura-neuronal-de-3-canales" tabindex="-1">2. Arquitectura Neuronal de 3 Canales <a class="header-anchor" href="#_2-arquitectura-neuronal-de-3-canales" aria-label="Permalink to &quot;2. Arquitectura Neuronal de 3 Canales&quot;">​</a></h2><p><strong>Tattoo You</strong> cuenta con un selector de canales de 3 posiciones que cubre todo el espectro tonal del clásico circuito de bulbos 100W 6L6:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Modo de Canal</th><th style="text-align:left;">Carácter del Tono</th><th style="text-align:left;">Aplicaciones Ideales</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>CLEAN</code></strong></td><td style="text-align:left;">Tono limpio inmaculado con compresión natural de bulbos, amplio margen dinámico y agudos suaves y cristalinos.</td><td style="text-align:left;">Ritmos de acordes equilibrados (<em>&quot;Beast of Burden&quot;</em>, <em>&quot;Tops&quot;</em>), arreglos de funk y baladas de soul.</td></tr><tr><td style="text-align:left;"><strong><code>CRUNCH</code></strong></td><td style="text-align:left;">Borde de ruptura orgánico con un cuerpo sólido en graves, medios contundentes y respuesta táctil inmediata al ataque de la púa.</td><td style="text-align:left;">Riffs de rock clásico icónicos (<em>&quot;Start Me Up&quot;</em>, <em>&quot;Little T&amp;A&quot;</em>, <em>&quot;Hang Fire&quot;</em>), acordes crujientes y ritmos de blues.</td></tr><tr><td style="text-align:left;"><strong><code>LEAD</code></strong></td><td style="text-align:left;">Saturación de bulbos abrasadora de alta ganancia con rico sustain armónico, sensación líquida al solear y graves enfocados.</td><td style="text-align:left;">Líneas melódicas cantadas, riffs de rock pesados, slide guitar (<em>&quot;Slave&quot;</em>, <em>&quot;Neighbours&quot;</em>) y solos sostenidos.</td></tr></tbody></table><hr><h2 id="_3-flujo-de-senal-y-guia-completa-de-controles" tabindex="-1">3. Flujo de Señal y Guía Completa de Controles <a class="header-anchor" href="#_3-flujo-de-senal-y-guia-completa-de-controles" aria-label="Permalink to &quot;3. Flujo de Señal y Guía Completa de Controles&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ ENTRADA GUITARRA ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ PHASE &#39;78 ]  ───►  [ SLAPBACK DELAY ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ PREAMP DE BULBOS 100W 6L6 (Clean / Crunch / Lead) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ EQ GRÁFICO 5 BANDAS ]  ───►  [ SIMULACIÓN GABINETE EVM-12L ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ MASTER OUTPUT ]  ───►  [ SALIDA ESTÉREO ]</span></span></code></pre></div><h3 id="_1-controles-principales-del-amplificador" tabindex="-1">1. Controles Principales del Amplificador <a class="header-anchor" href="#_1-controles-principales-del-amplificador" aria-label="Permalink to &quot;1. Controles Principales del Amplificador&quot;">​</a></h3><ul><li><strong><code>GAIN</code> (Volumen / Drive):</strong> Establece el nivel de señal de entrada hacia el amplificador (<code>1.0</code> = -9 dB, <code>7.0</code> = 0 dB Ganancia Unitaria, <code>10.0</code> = +4.5 dB de aumento).</li><li><strong><code>MASTER</code>:</strong> Volumen de salida analógica limpia (<code>1.0</code> = -36 dB volumen de habitación, <code>7.0</code> = 0 dB Ganancia Unitaria, <code>10.0</code> = +18 dB de aumento).</li><li><strong><code>CHANNEL SELECTOR</code>:</strong> Selector giratorio de 3 posiciones para alternar entre <code>CLEAN</code>, <code>CRUNCH</code> y <code>LEAD</code>.</li></ul><hr><h3 id="_2-ecualizador-grafico-de-5-bandas" tabindex="-1">2. Ecualizador Gráfico de 5 Bandas <a class="header-anchor" href="#_2-ecualizador-grafico-de-5-bandas" aria-label="Permalink to &quot;2. Ecualizador Gráfico de 5 Bandas&quot;">​</a></h3><p>Una recreación auténtica del clásico ecualizador activo de deslizadores Mesa con un interruptor <strong><code>EQ IN</code></strong> independiente y LED de estado:</p><ul><li><strong><code>80 Hz</code> (±12 dB):</strong> Golpe profundo de subgraves y resonancia del gabinete.</li><li><strong><code>240 Hz</code> (±12 dB):</strong> Control de graves-medios (boxiness). Reducirlo limpia el sonido &quot;embarrado&quot;.</li><li><strong><code>750 Hz</code> (±12 dB):</strong> Pegada de rango medio y &quot;ladrido&quot; vocal.</li><li><strong><code>2200 Hz / 2.2 kHz</code> (±12 dB):</strong> ¡La frecuencia de ataque! Aporta chasquido a la púa y mordida a los acordes.</li><li><strong><code>6600 Hz / 6.6 kHz</code> (±12 dB):</strong> Aire suave y brillo característico del altavoz EVM-12L.</li></ul><hr><h3 id="_3-suite-dual-de-fx-vintage-stones-78" tabindex="-1">3. Suite Dual de FX Vintage Stones &#39;78 <a class="header-anchor" href="#_3-suite-dual-de-fx-vintage-stones-78" aria-label="Permalink to &quot;3. Suite Dual de FX Vintage Stones &#39;78&quot;">​</a></h3><p>Integrado directamente antes de la etapa del preamplificador, replicando el flujo de señal exacto de la pedalera utilizado en discos clásicos:</p><h4 id="phase-78-phaser-optico-estilo-mxr-phase-100" tabindex="-1"><strong>Phase &#39;78 (Phaser Óptico Estilo MXR Phase 100)</strong> <a class="header-anchor" href="#phase-78-phaser-optico-estilo-mxr-phase-100" aria-label="Permalink to &quot;**Phase &#39;78 (Phaser Óptico Estilo MXR Phase 100)**&quot;">​</a></h4><p><em>Recrea la modulación óptica característica que se escucha en &quot;Beast of Burden&quot;, &quot;Shattered&quot; y &quot;Slave&quot;, proporcionando un barrido denso e hipnótico que cortaba a través del ataque de dos guitarras de Richards y Ronnie Wood.</em></p><ul><li><strong><code>PHASE &#39;78 Toggle &amp; LED Ámbar</code>:</strong> Activa o puentea el phaser con un consumo de CPU del 0%.</li><li><strong><code>SPEED</code> (<code>0.10 Hz</code> a <code>8.00 Hz</code>):</strong> Controla la tasa de modulación del LFO con visualización numérica dinámica en vivo.</li><li><strong><code>INTENS</code> (<code>0%</code> a <code>100%</code>):</strong> Controla la profundidad del barrido y la resonancia vocal.</li></ul><h4 id="slapback-delay-eco-de-cinta-analogica" tabindex="-1"><strong>Slapback Delay (Eco de Cinta Analógica)</strong> <a class="header-anchor" href="#slapback-delay-eco-de-cinta-analogica" aria-label="Permalink to &quot;**Slapback Delay (Eco de Cinta Analógica)**&quot;">​</a></h4><p><em>Recrea el cálido eco analógico de repetición única ajustado en el clásico punto dulce de 110 ms.</em></p><ul><li><strong><code>DELAY Toggle &amp; LED Rojo</code>:</strong> Activa o puentea el eco de cinta.</li><li><strong><code>TIME</code> (<code>20 ms</code> a <code>300 ms</code>):</strong> Establece el tiempo de retardo con lectura dinámica en milisegundos. Predeterminado: <code>110 ms</code> (el punto dulce clásico del slapback de Keith).</li><li><strong><code>REPEATS</code> (<code>0%</code> a <code>65%</code>):</strong> Controla la retroalimentación de la cinta (feedback).</li><li><strong><code>MIX</code> (<code>0%</code> a <code>50%</code>):</strong> Controla el equilibrio entre la señal con efecto y sin efecto (wet/dry).</li></ul><hr><h3 id="_4-simulacion-de-gabinete-de-estudio-1x12-evm-12l" tabindex="-1">4. Simulación de Gabinete de Estudio 1x12 EVM-12L <a class="header-anchor" href="#_4-simulacion-de-gabinete-de-estudio-1x12-evm-12l" aria-label="Permalink to &quot;4. Simulación de Gabinete de Estudio 1x12 EVM-12L&quot;">​</a></h3><p>El gabinete con puerto 1x12 cargado con un auténtico altavoz Electro-Voice EVM-12L de 200W ofrece un manejo de potencia inmenso, articulación de rango medio incolora y respuesta de graves ajustada. El selector <strong><code>CABINET</code></strong> ofrece 6 ubicaciones de micrófonos de estudio coherentes de fase más una opción de bypass:</p><ol><li><strong><code>SM57 SweetSpot</code>:</strong> Shure SM57 en el borde del cono (cap-edge) — ataque equilibrado, medios ricos y pegada sólida.</li><li><strong><code>SM57 Warm</code>:</strong> Shure SM57 en el cono exterior — graves profundos, agudos suaves y texturas cálidas.</li><li><strong><code>SM57 Direct</code>:</strong> Shure SM57 en el centro — articulación afilada como una navaja y mordida inmediata.</li><li><strong><code>SM57 BassPort</code>:</strong> Shure SM57 en el puerto frontal — golpe de graves extendido (80–100 Hz).</li><li><strong><code>U87 Studio</code>:</strong> Condensador de diafragma grande Neumann U87Ai — alta fidelidad, amplio rango dinámico y aire 3D abierto.</li><li><strong><code>U87 Warm</code>:</strong> Neumann U87Ai en zona cálida — cuerpo armónico denso sin dureza en agudos.</li><li><strong><code>Bypass IR</code>:</strong> Desactiva la simulación de gabinete interno para emparejar con cargadores de IR (Respuestas a Impulsos) de terceros externos.</li></ol><hr><h2 id="_4-presets-recomendados-y-guias-de-calibracion" tabindex="-1">4. Presets Recomendados y Guías de Calibración <a class="header-anchor" href="#_4-presets-recomendados-y-guias-de-calibracion" aria-label="Permalink to &quot;4. Presets Recomendados y Guías de Calibración&quot;">​</a></h2><h3 id="preset-1-start-me-up-tattoo-you-crunch-riff-power" tabindex="-1">Preset 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Riff Power) <a class="header-anchor" href="#preset-1-start-me-up-tattoo-you-crunch-riff-power" aria-label="Permalink to &quot;Preset 1: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Riff Power)&quot;">​</a></h3><ul><li><strong>Canal:</strong> <code>CRUNCH</code></li><li><strong>Gain:</strong> <code>7.5</code> | <strong>Master:</strong> <code>7.5</code></li><li><strong>EQ Gráfico 5-Bandas:</strong> <code>80Hz: +1.5dB</code> | <code>240Hz: -3.0dB</code> | <code>750Hz: +2.5dB</code> | <code>2.2kHz: +4.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code> (o <code>ON</code> con Mix @ <code>12%</code> para una sutil profundidad de sala de estudio)</li><li><strong>Gabinete:</strong> <code>SM57 Warm</code> (o <code>SM57 SweetSpot</code>)</li></ul><h3 id="preset-2-beast-of-burden-shattered-el-limpio-con-phase-liquido" tabindex="-1">Preset 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (El Limpio con Phase Líquido) <a class="header-anchor" href="#preset-2-beast-of-burden-shattered-el-limpio-con-phase-liquido" aria-label="Permalink to &quot;Preset 2: &quot;Beast of Burden&quot; / &quot;Shattered&quot; (El Limpio con Phase Líquido)&quot;">​</a></h3><ul><li><strong>Canal:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>7.0</code> | <strong>Master:</strong> <code>7.0</code></li><li><strong>EQ Gráfico 5-Bandas:</strong> <code>80Hz: 0dB</code> | <code>240Hz: -2.0dB</code> | <code>750Hz: +2.0dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +1.5dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>0.80 Hz</code> | Intensity: <code>60%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>110 ms</code> | Repeats: <code>20%</code> | Mix: <code>25%</code></li><li><strong>Gabinete:</strong> <code>SM57 SweetSpot</code> (o <code>U87 Studio</code>)</li></ul><h3 id="preset-3-emotional-rescue-dance-part-1-funk-rock-groove-ajustado" tabindex="-1">Preset 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (Funk-Rock &amp; Groove Ajustado) <a class="header-anchor" href="#preset-3-emotional-rescue-dance-part-1-funk-rock-groove-ajustado" aria-label="Permalink to &quot;Preset 3: &quot;Emotional Rescue&quot; / &quot;Dance Part 1&quot; (Funk-Rock &amp; Groove Ajustado)&quot;">​</a></h3><ul><li><strong>Canal:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>6.5</code> | <strong>Master:</strong> <code>8.0</code></li><li><strong>EQ Gráfico 5-Bandas:</strong> <code>80Hz: -1.0dB</code> | <code>240Hz: -4.0dB</code> | <code>750Hz: +1.0dB</code> | <code>2.2kHz: +3.5dB</code> | <code>6.6kHz: +3.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>1.20 Hz</code> | Intensity: <code>40%</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code></li><li><strong>Gabinete:</strong> <code>SM57 Direct</code></li></ul><h3 id="preset-4-slave-neighbours-lineas-y-solos-de-bulbo-cantantes" tabindex="-1">Preset 4: &quot;Slave&quot; / &quot;Neighbours&quot; (Líneas y Solos de Bulbo Cantantes) <a class="header-anchor" href="#preset-4-slave-neighbours-lineas-y-solos-de-bulbo-cantantes" aria-label="Permalink to &quot;Preset 4: &quot;Slave&quot; / &quot;Neighbours&quot; (Líneas y Solos de Bulbo Cantantes)&quot;">​</a></h3><ul><li><strong>Canal:</strong> <code>LEAD</code></li><li><strong>Gain:</strong> <code>8.0</code> | <strong>Master:</strong> <code>7.0</code></li><li><strong>EQ Gráfico 5-Bandas:</strong> <code>80Hz: +2.0dB</code> | <code>240Hz: -1.5dB</code> | <code>750Hz: +3.5dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>140 ms</code> | Repeats: <code>30%</code> | Mix: <code>25%</code></li><li><strong>Gabinete:</strong> <code>SM57 Direct</code> (o <code>U87 Studio</code>)</li></ul><hr><h2 id="_5-especificaciones-tecnicas-y-soporte-de-plataformas" tabindex="-1">5. Especificaciones Técnicas y Soporte de Plataformas <a class="header-anchor" href="#_5-especificaciones-tecnicas-y-soporte-de-plataformas" aria-label="Permalink to &quot;5. Especificaciones Técnicas y Soporte de Plataformas&quot;">​</a></h2><ul><li><strong>Formatos de Plugin:</strong> VST3 (64-bit), Aplicación Standalone (.exe).</li><li><strong>Sistemas Operativos:</strong><ul><li><strong>Windows:</strong> Windows 10 / Windows 11 (x64) - <em>Disponible Ahora</em>.</li><li><strong>macOS:</strong> Binario Universal (Apple Silicon M1/M2/M3/M4 &amp; Intel x64) / AU, VST3, Standalone - <em>Próximamente</em>.</li><li><strong>Linux:</strong> Ubuntu / Debian / Arch (VST3, CLAP, Standalone) - <em>Próximamente</em>.</li></ul></li><li><strong>Motor de Procesamiento:</strong> Arquitectura WaveNet de Modelado Neuronal de Amplificadores (NAM) + Convolución DSP en tiempo real.</li><li><strong>Resolución de Audio Interna:</strong> Procesamiento de coma flotante de doble precisión de 64 bits.</li><li><strong>Tasas de Muestreo Soportadas:</strong> 44.1 kHz, 48 kHz, 88.2 kHz, 96 kHz, 176.4 kHz, 192 kHz.</li><li><strong>Latencia:</strong> Cero latencia (0 muestras) para seguimiento y monitoreo en vivo.</li></ul><hr>`,50)),o("div",l,[e[1]||(e[1]=o("div",{class:"rock-card-contact-title"},"Preguntas, Comentarios y Compartir Mezclas",-1)),e[2]||(e[2]=o("p",{class:"rock-card-contact-desc"},"Tattoo You fue calibrado por guitarristas para guitarristas. Si tienes preguntas, comentarios o quieres compartir pistas creadas con Tattoo You, ponte en contacto con nosotros:",-1)),o("div",c,[e[0]||(e[0]=o("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),o("button",{class:"rock-copy-btn",onClick:t},d(a.value),1)])])]))}});export{h as __pageData,b as default};
